export type Model3DAnimationName = keyof typeof MODEL3D_ANIMATION_TEMPLATES

/**
 * Lowercased effect names for the native 3D model animations, as they arrive
 * from the animation API (which lowercases `effect`). Used to exclude these
 * effects from grpId/bldLst generation — the reference deck emits neither for
 * 3D model animations (mirrors how media animations are handled).
 */
export const MODEL3D_ANIMATION_EFFECT_NAMES: ReadonlySet<string> = new Set(
	Object.keys(MODEL3D_ANIMATION_TEMPLATES).map(k => k.toLowerCase())
)

export function normalizeModel3DAnimationEffectName(effect?: string): string {
	const lower = (effect || '').toLowerCase()
	if (!lower || MODEL3D_ANIMATION_EFFECT_NAMES.has(lower)) return lower

	let compact = ''
	for (const ch of lower) {
		if (ch >= 'a' && ch <= 'z') compact += ch
		else if (ch >= '0' && ch <= '9') compact += ch
	}
	if (compact === 'jumpandturn' || compact === 'jumpturn') return 'jumpandturn'
	return lower
}

/** True when `effect` names one of the native 3D model animations. */
export function isModel3DAnimationEffect(effect?: string): boolean {
	return MODEL3D_ANIMATION_EFFECT_NAMES.has(normalizeModel3DAnimationEffectName(effect))
}
